extends Node2D

# Player settings
@export var player_speed = 200.0
@export var player_collision_radius = 24.0
@export var player_scale = 0.7

# Jellyfish (creature) settings
@export var flee_speed = 70.0       # well below player speed (35% of player_speed)
@export var panic_radius = 120.0    # intensity 3/10 – smaller so they bolt later
@export var total_jellyfish = 3
@export var jellyfish_collision_radius = 20.0
@export var jellyfish_scale = 0.7

# Goal zone (tide pool)
@export var goal_radius = 50.0      # larger pool for easier herding
@export var goal_position = Vector2(780, 420)

# Obstacles (rocks)
@export var rock_radius = 30.0
@export var rock_scale = 0.8
@export var rock_positions = [
    Vector2(350, 250),
    Vector2(600, 320),
    Vector2(500, 450),
]

# Sunrise timer
@export var max_sun_time = 60.0
var sun_time_left = max_sun_time

# State management
var state = "title"
var player_area: Area2D
var player_sprite: Sprite2D
var jellyfish_list = []          # [{ area, sprite, settled }]
var tide_pool_area: Area2D
var rock_areas = []
var settled_count = 0

# UI
var status_label: Label

func _ready():
    # --- Background ---
    var bg = Sprite2D.new()
    bg.texture = load("res://assets/level_0_bg_00019_.png")
    bg.centered = false
    bg.position = Vector2.ZERO
    bg.z_index = -1
    add_child(bg)

    # --- Tide pool (goal) ---
    tide_pool_area = Area2D.new()
    tide_pool_area.position = goal_position
    var pool_sprite = Sprite2D.new()
    pool_sprite.texture = load("res://assets/extra_tide_pool_00001_.png")
    pool_sprite.scale = Vector2(1.2, 1.2)
    tide_pool_area.add_child(pool_sprite)
    var pool_collision = CollisionShape2D.new()
    var pool_circle = CircleShape2D.new()
    pool_circle.radius = goal_radius
    pool_collision.shape = pool_circle
    tide_pool_area.add_child(pool_collision)
    tide_pool_area.area_entered.connect(_on_jellyfish_enter_pool)
    add_child(tide_pool_area)

    # --- Rocks (obstacles) ---
    for pos in rock_positions:
        var rock = Area2D.new()
        rock.position = pos
        var rock_sprite = Sprite2D.new()
        rock_sprite.texture = load("res://assets/extra_rock_00001_.png")
        rock_sprite.scale = Vector2(rock_scale, rock_scale)
        rock.add_child(rock_sprite)
        var rock_collision = CollisionShape2D.new()
        var rock_circle = CircleShape2D.new()
        rock_circle.radius = rock_radius
        rock_collision.shape = rock_circle
        rock.add_child(rock_collision)
        add_child(rock)
        rock_areas.append({"area": rock, "radius": rock_radius})

    # --- Player (cat) ---
    player_area = Area2D.new()
    player_area.position = Vector2(150, 400)
    player_sprite = Sprite2D.new()
    var resting_texture = load("res://assets/hero_sprite_00020_.png")
    var walk_texture = load("res://assets/hero_walk_00001_.png")
    Anim.set_poses(player_sprite, resting_texture, walk_texture)
    player_sprite.scale = Vector2(player_scale, player_scale)
    player_area.add_child(player_sprite)
    var player_shape = CollisionShape2D.new()
    var player_circle = CircleShape2D.new()
    player_circle.radius = player_collision_radius
    player_shape.shape = player_circle
    player_area.add_child(player_shape)
    add_child(player_area)

    # --- Jellyfish ---
    var jelly_positions = [
        Vector2(300, 200),
        Vector2(550, 150),
        Vector2(450, 350),
    ]
    for i in total_jellyfish:
        var jelly = Area2D.new()
        jelly.position = jelly_positions[i] if i < jelly_positions.size() else Vector2(randf_range(100, 900), randf_range(100, 500))
        var j_sprite = Sprite2D.new()
        j_sprite.texture = load("res://assets/key_item_00017_.png")
        j_sprite.scale = Vector2(jellyfish_scale, jellyfish_scale)
        jelly.add_child(j_sprite)
        var j_shape = CollisionShape2D.new()
        var j_circle = CircleShape2D.new()
        j_circle.radius = jellyfish_collision_radius
        j_shape.shape = j_circle
        jelly.add_child(j_shape)
        add_child(jelly)
        jellyfish_list.append({
            "area": jelly,
            "sprite": j_sprite,
            "settled": false,
            "radius": jellyfish_collision_radius
        })

    # --- UI Canvas ---
    var canvas = CanvasLayer.new()
    add_child(canvas)
    status_label = Label.new()
    status_label.position = Vector2(20, 20)
    canvas.add_child(status_label)

    # Headless / level skip
    if DisplayServer.get_name() == "headless" or Game.level > 0:
        state = "playing"

func _on_jellyfish_enter_pool(area: Area2D):
    if state != "playing":
        return
    for j in jellyfish_list:
        if j.area == area and not j.settled:
            j.settled = true
            settled_count += 1
            Sfx.play("pickup")
            Anim.pop(j.sprite)  # little celebration animation
            if settled_count >= total_jellyfish:
                _win()
            break

func _win():
    state = "won"
    Sfx.play("win")
    status_label.text = "All jellyfish returned to the sea! Level complete."
    Game.level_complete()

func _process(delta):
    # --- State handlers ---
    if state == "title":
        status_label.text = "BLINDSIGHT BEACH - Press Enter to start"
        if Input.is_action_just_pressed("ui_accept"):
            state = "playing"
        return

    if state == "won":
        return

    if state == "over":
        if Input.is_action_just_pressed("ui_accept"):
            get_tree().reload_current_scene()
        return

    # ----- PLAYING -----
    # Sunrise countdown
    sun_time_left -= delta
    if sun_time_left <= 0.0:
        state = "over"
        Sfx.play("lose")
        status_label.text = "The sun rose... Press Enter to restart"
        return

    # Player movement
    var input_dir = Vector2.ZERO
    if Input.is_action_pressed("ui_right"): input_dir.x += 1.0
    if Input.is_action_pressed("ui_left"): input_dir.x -= 1.0
    if Input.is_action_pressed("ui_down"): input_dir.y += 1.0
    if Input.is_action_pressed("ui_up"): input_dir.y -= 1.0
    var velocity = input_dir.normalized() * player_speed * delta
    var new_player_pos = player_area.position + velocity
    new_player_pos = _clamp_with_obstacles(new_player_pos, player_collision_radius, true)
    new_player_pos = new_player_pos.clamp(Vector2.ZERO, Vector2(1024, 576))
    player_area.position = new_player_pos

    var is_moving = velocity.length_squared() > 0.1
    Anim.walk(player_sprite, is_moving, input_dir.x)

    # Jellyfish AI
    for jelly in jellyfish_list:
        if jelly.settled:
            Anim.hover(jelly.sprite)
            continue
        var j_area = jelly.area
        var to_player = player_area.position - j_area.position
        var dist = to_player.length()
        if dist < panic_radius and dist > 0.001:
            var flee_dir = -to_player.normalized()
            var move = flee_dir * flee_speed * delta
            var new_pos = j_area.position + move
            new_pos = _clamp_with_obstacles(new_pos, jelly.radius, false)
            new_pos = new_pos.clamp(Vector2.ZERO, Vector2(1024, 576))
            j_area.position = new_pos
        # animate: jellyfish drift, use hover
        Anim.hover(jelly.sprite)

    # Update UI
    var secs = max(0, int(ceil(sun_time_left)))
    status_label.text = "Sunrise: %ds   Jellyfish: %d/%d" % [secs, settled_count, total_jellyfish]


func _clamp_with_obstacles(pos: Vector2, own_radius: float, is_player: bool) -> Vector2:
    # Push out of any overlapping rock obstacle
    for rock in rock_areas:
        var rock_center = rock.area.position
        var dist_to = pos.distance_to(rock_center)
        var min_dist = own_radius + rock.radius
        if dist_to < min_dist and dist_to > 0.001:
            var push_dir = (pos - rock_center).normalized()
            pos = rock_center + push_dir * min_dist
    return pos

extends Node2D

# Difficulty tuning (level 1 of 4, intensity 3/10)
var speed = 200.0
var patrol_speed = 93.5    # 15% slower than 4/10 reference (110 * 0.85)
var hunter_speed = 76.5    # 90 * 0.85
var frightened_speed = 55.25  # 65 * 0.85
var power_duration = 7.0   # longer than 6.0
var starting_lives = 3
var hit_cooldown_time = 1.2
var player_half_size = 14.0

var lives = starting_lives
var score = 0
var total_dots = 0
var power_left = 0.0
var hit_cooldown = 0.0
var state = "title"
var player: Area2D
var player_sprite: Sprite2D
var player_spawn = Vector2(512, 490)
var status_label: Label
var wall_rects: Array[Rect2] = []
var ghosts: Array[Area2D] = []
var ghost_sprites: Array[Sprite2D] = []
var ghost_tints: Array[Color] = []
var ghost_home: Array[Vector2] = []
var ghost_routes: Array[Array] = []
var ghost_route_index: Array[int] = []
var ghost_frightened: Array[bool] = []
var pellet_positions = [Vector2(60, 60), Vector2(964, 60), Vector2(60, 516), Vector2(964, 516)]

func _ready():
    # Background
    var bg = Sprite2D.new()
    bg.texture = load("res://assets/level_0_bg.png")
    bg.centered = false
    bg.position = Vector2.ZERO
    bg.z_index = -1
    add_child(bg)

    # Walls
    var border_walls = [
        Rect2(0, 0, 1024, 20), Rect2(0, 556, 1024, 20),
        Rect2(0, 0, 20, 576), Rect2(1004, 0, 20, 576)
    ]
    var inner_walls = [
        Rect2(200, 150, 180, 120),
        Rect2(500, 250, 150, 100),
        Rect2(700, 400, 120, 100),
        Rect2(300, 380, 160, 90)
    ]
    var wall_texture = load("res://assets/extra_garden_wall.png")
    for rect in border_walls + inner_walls:
        wall_rects.append(rect)
        var wall_sprite = Sprite2D.new()
        wall_sprite.texture = wall_texture
        wall_sprite.centered = false
        wall_sprite.position = rect.position
        wall_sprite.scale = Vector2(rect.size.x / 128.0, rect.size.y / 128.0)
        add_child(wall_sprite)

    # Player
    player = Area2D.new()
    player.position = player_spawn
    var resting_tex = load("res://assets/hero_sprite.png")
    var walk_tex = load("res://assets/hero_walk.png")
    player_sprite = Sprite2D.new()
    player_sprite.texture = resting_tex
    player.add_child(player_sprite)
    Anim.set_poses(player_sprite, resting_tex, walk_tex)

    var player_shape = CollisionShape2D.new()
    var player_circle = CircleShape2D.new()
    player_circle.radius = player_half_size
    player_shape.shape = player_circle
    player.add_child(player_shape)
    player.area_entered.connect(_on_player_touched)
    add_child(player)

    # Dots (stars)
    var small_dot_positions = []
    for y in range(50, 526+1, 110):
        for x in range(50, 974+1, 110):
            var pos = Vector2(x, y)
            var inside_wall = false
            for w in wall_rects:
                if w.has_point(pos):
                    inside_wall = true
                    break
            if inside_wall:
                continue
            var is_pellet = false
            for pel in pellet_positions:
                if pos.distance_to(pel) < 10:
                    is_pellet = true
                    break
            if not is_pellet:
                _spawn_dot(pos, false)

    for pel in pellet_positions:
        _spawn_dot(pel, true)

    # Ghosts (shadow moths)
    var moth_tex = load("res://assets/extra_patrol_moth.png")
    # Patrol 1
    var route1 = [Vector2(100, 100), Vector2(900, 100), Vector2(900, 500), Vector2(100, 500)]
    _spawn_ghost(Vector2(100, 100), Color(1.3, 0.5, 0.5), route1, moth_tex)
    # Patrol 2
    var route2 = [Vector2(300, 200), Vector2(700, 200), Vector2(700, 400), Vector2(300, 400)]
    _spawn_ghost(Vector2(300, 200), Color(0.5, 0.7, 1.3), route2, moth_tex)
    # Hunter
    _spawn_ghost(Vector2(512, 300), Color(0.7, 1.0, 0.5), [], moth_tex)

    # UI
    var canvas = CanvasLayer.new()
    add_child(canvas)
    status_label = Label.new()
    status_label.position = Vector2(20, 20)
    canvas.add_child(status_label)

    if DisplayServer.get_name() == "headless" or Game.level > 0:
        state = "playing"

func _spawn_dot(pos: Vector2, is_pellet: bool):
    var dot = Area2D.new()
    dot.position = pos
    var sprite = Sprite2D.new()
    sprite.texture = load("res://assets/key_item.png")
    if is_pellet:
        sprite.scale = Vector2(0.45, 0.45)
        sprite.modulate = Color(1.4, 1.2, 0.5)  # golden pellet
    else:
        sprite.scale = Vector2(0.18, 0.18)
    dot.add_child(sprite)
    var shape = CollisionShape2D.new()
    var circle = CircleShape2D.new()
    circle.radius = 8.0
    shape.shape = circle
    dot.add_child(shape)
    dot.area_entered.connect(_on_dot_entered.bind(dot, is_pellet))
    add_child(dot)
    total_dots += 1

func _spawn_ghost(pos: Vector2, tint: Color, route: Array, texture: Texture2D):
    var ghost = Area2D.new()
    ghost.position = pos
    var sprite = Sprite2D.new()
    sprite.texture = texture
    sprite.modulate = tint
    sprite.scale = Vector2(0.6, 0.6)
    ghost.add_child(sprite)
    var shape = CollisionShape2D.new()
    var circle = CircleShape2D.new()
    circle.radius = 14.0
    shape.shape = circle
    ghost.add_child(shape)
    add_child(ghost)
    ghosts.append(ghost)
    ghost_sprites.append(sprite)
    ghost_tints.append(tint)
    ghost_home.append(pos)
    ghost_routes.append(route)
    ghost_route_index.append(0)
    ghost_frightened.append(false)

func _on_dot_entered(area: Area2D, dot: Area2D, is_pellet: bool):
    if state != "playing" or area != player:
        return
    dot.queue_free()
    score += 1
    Sfx.play("pickup")
    if is_pellet:
        power_left = power_duration
        for i in ghosts.size():
            ghost_frightened[i] = true
    if score >= total_dots:
        state = "won"
        Sfx.play("win")
        status_label.text = "The stars are gathered - level complete!"
        Game.level_complete()

func _on_player_touched(area: Area2D):
    if state != "playing":
        return
    var gi = ghosts.find(area)
    if gi == -1:
        return
    if ghost_frightened[gi]:
        Sfx.play("pickup")
        Anim.pop(ghost_sprites[gi])
        ghosts[gi].position = ghost_home[gi]
        ghost_frightened[gi] = false
        return
    if hit_cooldown > 0.0:
        return
    lives -= 1
    hit_cooldown = hit_cooldown_time
    player.modulate = Color(1.0, 0.45, 0.45)
    Anim.flash(player_sprite)
    player.position = player_spawn
    Sfx.play("hit")
    if lives <= 0:
        state = "over"
        Sfx.play("lose")
        status_label.text = "The shadow moths won...  Press Enter to restart"

func _hits_wall(pos: Vector2) -> bool:
    var half = Vector2(player_half_size, player_half_size)
    var player_rect = Rect2(pos - half, half * 2.0)
    for w in wall_rects:
        if player_rect.intersects(w):
            return true
    return false

func _process(delta):
    if state == "title":
        status_label.text = "Stellar Wanderer - Press Enter to start"
        if Input.is_action_just_pressed("ui_accept"):
            state = "playing"
        return
    if state == "won":
        return
    if state == "over":
        if Input.is_action_just_pressed("ui_accept"):
            get_tree().reload_current_scene()
        return

    if hit_cooldown > 0.0:
        hit_cooldown -= delta
        if hit_cooldown <= 0.0:
            player.modulate = Color(1, 1, 1)

    if power_left > 0.0:
        power_left -= delta
        if power_left <= 0.0:
            for i in ghosts.size():
                ghost_frightened[i] = false

    # Ghost movement
    for i in ghosts.size():
        var ghost = ghosts[i]
        var sprite = ghost_sprites[i]
        if ghost_frightened[i]:
            sprite.modulate = Color(0.5, 0.6, 1.4)
            var away = (ghost.position - player.position).normalized()
            if away.length_squared() < 0.01:
                away = Vector2.RIGHT
            ghost.position += away * frightened_speed * delta
            ghost.position = ghost.position.clamp(Vector2(40, 40), Vector2(984, 536))
        else:
            sprite.modulate = ghost_tints[i]
            if ghost_routes[i].size() > 0:
                var target = ghost_routes[i][ghost_route_index[i]]
                ghost.position = ghost.position.move_toward(target, patrol_speed * delta)
                if ghost.position.distance_to(target) < 2.0:
                    ghost_route_index[i] = (ghost_route_index[i] + 1) % ghost_routes[i].size()
            else:
                var toward = (player.position - ghost.position).normalized()
                if toward.length_squared() < 0.01:
                    toward = Vector2.RIGHT
                ghost.position += toward * hunter_speed * delta
        Anim.hover(sprite)   # floating moth animation

    # Player movement
    var velocity = Vector2.ZERO
    if Input.is_action_pressed("ui_right"):
        velocity.x += 1.0
    if Input.is_action_pressed("ui_left"):
        velocity.x -= 1.0
    if Input.is_action_pressed("ui_down"):
        velocity.y += 1.0
    if Input.is_action_pressed("ui_up"):
        velocity.y -= 1.0
    var motion = velocity.normalized() * speed * delta

    var new_x = player.position + Vector2(motion.x, 0)
    if not _hits_wall(new_x):
        player.position = new_x
    var new_y = player.position + Vector2(0, motion.y)
    if not _hits_wall(new_y):
        player.position = new_y

    # Player animation
    var is_moving = velocity.length_squared() > 0.01
    var dir_x = sign(velocity.x) if is_moving else 0.0
    Anim.walk(player_sprite, is_moving, dir_x)

    # HUD
    var power_note = ""
    if power_left > 0.0:
        power_note = "   POWER %ds!" % int(ceil(power_left))
    status_label.text = "Stars: %d / %d   Lives: %d%s" % [score, total_dots, lives, power_note]

extends Node2D

# Tuning variables
const PLAYER_SPEED = 200.0
const PATROL_SPEED = 127.0
const HUNTER_SPEED = 105.0
const FRIGHTENED_SPEED = 65.0
const POWER_DURATION = 5.0
const STARTING_LIVES = 3
const HIT_COOLDOWN = 1.2
const PLAYER_HALF_SIZE = 14.0
const MOTH_HALF_SIZE = 14.0

var lives = STARTING_LIVES
var score = 0
var total_dots = 0
var power_left = 0.0
var hit_cooldown = 0.0
var state = "title"
var player: Area2D
var player_sprite: Sprite2D
var player_spawn = Vector2(512, 490)
var status_label: Label
var walls: Array = []
var ghosts: Array = []
var ghost_sprites: Array = []
var ghost_tints: Array = []
var ghost_home: Array = []
var ghost_routes: Array = []
var ghost_route_index: Array = []
var ghost_frightened: Array = []

# Pellet positions (corners)
var pellet_positions = [Vector2(75, 70), Vector2(950, 70), Vector2(75, 490), Vector2(950, 490)]

func _ready():
    # Background
    var bg = Sprite2D.new()
    bg.texture = load("res://assets/level_1_bg.png")
    bg.centered = false
    bg.position = Vector2.ZERO
    bg.z_index = -1
    add_child(bg)

    # Walls (Rect2 list, same as example but with tiled sprite)
    walls = [
        Rect2(0, 0, 1024, 20), Rect2(0, 556, 1024, 20),
        Rect2(0, 0, 20, 576), Rect2(1004, 0, 20, 576),
    ]
    for row_y in [110, 250, 390]:
        for block_x in [130, 350, 560, 780]:
            walls.append(Rect2(block_x, row_y, 120, 60))
    var wall_tex = load("res://assets/extra_garden_wall.png")
    for r in walls:
        var wall_sprite = Sprite2D.new()
        wall_sprite.texture = wall_tex
        wall_sprite.texture_repeat = CanvasItem.TEXTURE_REPEAT_ENABLED
        wall_sprite.centered = false
        wall_sprite.position = r.position
        wall_sprite.scale = Vector2(r.size.x / 128.0, r.size.y / 128.0)
        add_child(wall_sprite)

    # Player with animated poses
    player = Area2D.new()
    player.position = player_spawn
    player_sprite = Sprite2D.new()
    var hero_rest = load("res://assets/hero_sprite.png")
    var hero_walk = load("res://assets/hero_walk.png")
    player_sprite.texture = hero_rest
    player.add_child(player_sprite)
    var player_shape = CollisionShape2D.new()
    var player_circle = CircleShape2D.new()
    player_circle.radius = PLAYER_HALF_SIZE
    player_shape.shape = player_circle
    player.add_child(player_shape)
    player.area_entered.connect(_on_player_touched)
    add_child(player)
    Anim.set_poses(player_sprite, hero_rest, hero_walk)

    # Dots (stars)
    var dot_tex = load("res://assets/key_item.png")
    # Grid of open positions, excluding those inside walls
    for y in [70, 210, 350, 490]:
        for x in [75, 160, 300, 410, 515, 620, 730, 840, 950]:
            var pos = Vector2(x, y)
            if not pos in pellet_positions and not _is_wall_point(pos):
                _spawn_dot(pos, false, dot_tex)
    # Extra corridor dots
    for y in [140, 280, 420]:
        for x in [75, 300, 515, 730, 950]:
            var pos = Vector2(x, y)
            if not _is_wall_point(pos):
                _spawn_dot(pos, false, dot_tex)
    # Pellets
    for pos in pellet_positions:
        _spawn_dot(pos, true, dot_tex)

    # Moths (ghosts)
    var moth_tex = load("res://assets/extra_patrol_moth.png")
    # Patrol 1 – long zigzag
    _spawn_moth(Vector2(75, 70), Color(0.7, 0.5, 0.9), [
        Vector2(300, 70), Vector2(300, 280), Vector2(75, 280),
        Vector2(75, 490), Vector2(300, 490), Vector2(300, 280),
        Vector2(75, 280), Vector2(75, 70)
    ], moth_tex)
    # Patrol 2 – the mirrored route
    _spawn_moth(Vector2(950, 70), Color(0.5, 0.7, 0.9), [
        Vector2(730, 70), Vector2(730, 280), Vector2(950, 280),
        Vector2(950, 490), Vector2(730, 490), Vector2(730, 280),
        Vector2(950, 280), Vector2(950, 70)
    ], moth_tex)
    # Hunter – no route
    _spawn_moth(Vector2(515, 280), Color(0.9, 0.6, 0.8), [], moth_tex)

    # UI label on CanvasLayer
    var canvas = CanvasLayer.new()
    add_child(canvas)
    status_label = Label.new()
    status_label.position = Vector2(20, 20)
    canvas.add_child(status_label)

    # Start state
    if DisplayServer.get_name() == "headless" or Game.level > 0:
        state = "playing"

func _is_wall_point(pos: Vector2) -> bool:
    for w in walls:
        if w.has_point(pos):
            return true
    return false

func _spawn_dot(pos: Vector2, is_pellet: bool, texture: Texture2D):
    var dot = Area2D.new()
    dot.position = pos
    var sprite = Sprite2D.new()
    sprite.texture = texture
    if is_pellet:
