func _process(delta):
    if state == "title":
        status_label.text = "STELLAR GARDEN - Press Enter to start"
        if Input.is_action_just_pressed("ui_accept"):
            state = "playing"
        return

    if state == "won":
        return # Wait for Game level complete logic? Or just stay here.

    if state == "over":
        status_label.text += "\n(Press Enter to restart)"
        if Input.is_action_just_pressed("ui_accept"):
            get_tree().reload_current_scene()
        return

    if hit_cooldown > 0.0:
        hit_cooldown -= delta
        if hit_cooldown <= 0.0:
            player.modulate = Color(1, 1, 1) # Reset modulate

    if power_left > 0.0:
        power_left -= delta
        if power_left <= 0.0:
            for i in ghosts.size():
                ghost_frightened[i] = false

    # Ghost Logic
    for i in ghosts.size():
        var ghost = ghosts[i]
        var sprite = ghost_sprites[i]

        if ghost_frightened[i]:
            sprite.modulate = Color(0.5, 0.6, 1.4) # Blue

            # Flee logic: move away from player
            var away = (ghost.position - player.position).normalized()
            if away.is_zero_approx():
                away = Vector2(1, 0)
            ghost.position += away * frightened_speed * delta

