            sprite.modulate = ghost_tints[i] # Restore original tint

            if ghost_routes[i].size() > 0:
                # Patrol logic - use move_toward
                var target = ghost_routes[i][ghost_route_index[i]]
                ghost.position = ghost.position.move_toward(target, patrol_speed * delta)

                if ghost.position.distance_to(target) < 10.0:
                    ghost_route_index[i] = (ghost_route_index[i] + 1) % ghost_routes[i].size()
            else:
                # Hunter logic: move towards player - use move_toward
                var dir = (player.position - ghost.position).normalized()
