            player.position = new_y
    else:
        Anim.walk(player_sprite, false, 0.0)

    # Status update
    var power_note = ""
    if power_left > 0.0:
        power_note = "   POWER %ds!" % int(ceil(power_left))

    status_label.text = "Stars: %d / %d   Lives: %d%s" % [score, total_dots, lives, power_note]

