		return
	lives -= 1
	hit_cooldown = hit_cooldown_time
	player.position = player_spawn
	player.modulate = Color(1.0, 0.45, 0.45)
	Sfx.play("hit")
	if lives <= 0:
		state = "over"
		Sfx.play("lose")
		status_label.text = "The wardens caught the glutton...  Press Enter to restart"

func _hits_wall(pos: Vector2) -> bool:
	var half = Vector2(player_half_size, player_half_size)
	var player_rect = Rect2(pos - half, half * 2.0)
	for w in wall_rects:
		if player_rect.intersects(w):
			return true
	return false

func _process(delta):
	if state == "title":
		status_label.text = "GLUTTON GROVE - Press Enter to start"
		if Input.is_action_just_pressed("ui_accept"):
			state = "playing"
		return
	if state == "won":
		return
	if state == "over":
		if Input.is_action_just_pressed("ui_accept"):
			get_tree().reload_current_scene()
		return

	if hit_cooldown > 0.0:
		hit_cooldown -= delta
		if hit_cooldown <= 0.0:
			player.modulate = Color(1, 1, 1)

	if power_left > 0.0:
		power_left -= delta
		if power_left <= 0.0:
			for i in ghosts.size():
				ghost_frightened[i] = false

	var player_vel = Vector2.ZERO
	if Input.is_action_pressed("ui_right"):
		player_vel.x += 1.0
	if Input.is_action_pressed("ui_left"):
		player_vel.x -= 1.0
	if Input.is_action_pressed("ui_down"):
		player_vel.y += 1.0
	if Input.is_action_pressed("ui_up"):
		player_vel.y -= 1.0

	var is_moving = player_vel.length_squared() > 0
	var motion = player_vel.normalized() * player_speed * delta

	var new_x = player.position + Vector2(motion.x, 0)
	if not _hits_wall(new_x):
		player.position = new_x
	var new_y = player.position + Vector2(0, motion.y)
	if not _hits_wall(new_y):
		player.position = new_y

	# Animation for player (hero) using Anim autoload
	var hero_sprite = player.get_child(0) as Sprite2D
	if hero_sprite:
		Anim.walk(hero_sprite, is_moving, player_vel.x)

	# Ghost movement and animation
	for i in ghosts.size():
		var ghost = ghosts[i]
		var sprite = ghost_sprites[i]
		if ghost_frightened[i]:
			sprite.modulate = Color(0.5, 0.6, 1.4)
			var away = (ghost.position - player.position).normalized()
			ghost.position += away * frightened_speed * delta
			ghost.position = ghost.position.clamp(Vector2(40, 40), Vector2(984, 536))
		else:
			sprite.modulate = ghost_tints[i]
			var target = ghost.global_position
			if ghost_routes[i].size() > 0:
				var dist_to_player = ghost.position.distance_to(player.position)
				if dist_to_player < ghost_detection_radius:
					target = player.position
				else:
					target = ghost_routes[i][ghost_route_index[i]]
				ghost.position = ghost.position.move_toward(target, patrol_speed * delta)
				if not ghost_frightened[i] and dist_to_player >= ghost_detection_radius and ghost.position.distance_to(ghost_routes[i][ghost_route_index[i]]) < 2.0:
					ghost_route_index[i] = (ghost_route_index[i] + 1) % ghost_routes[i].size()
			else:
				var toward = (player.position - ghost.position).normalized()
				ghost.position += toward * hunter_speed * delta
		# Animate ghost as floating
		Anim.hover(sprite)

	var power_note = ""
	if power_left > 0.0:
		power_note = "   POWER %ds!" % int(ceil(power_left))
	status_label.text = "Berries: %d / %d   Lives: %d%s" % [score, total_dots, lives, power_note]

extends Node2D

# Tunable difficulty numbers (level 4, 9/10 intensity)
var player_speed = 200.0
var patrol_speed = 190.0          # increased from 110
var hunter_speed = 160.0          # increased from 90
var frightened_speed = 110.0      # increased from 65
var power_duration = 2.8          # shorter
var starting_lives = 3
var hit_cooldown_time = 1.2
var player_half_size = 14.0

# Game state
var lives = starting_lives
var score = 0
var total_dots = 0
var power_left = 0.0
var hit_cooldown = 0.0
var state = "title"

# References
var player: Area2D
var player_sprite: Sprite2D
var player_spawn = Vector2(512, 490)
var status_label: Label
var walls: Array = []             # Rect2s for collision
var ghosts: Array = []
var ghost_sprites: Array = []
var ghost_tints: Array = []
var ghost_home: Array = []
var ghost_routes: Array = []
var ghost_route_index: Array = []
var ghost_frightened: Array = []
var pellet_positions = [Vector2(75, 70), Vector2(950, 70), Vector2(75, 490), Vector2(950, 490)]

func _ready() -> void:
    # Background (now using the appropriate level image)
    var bg = Sprite2D.new()
    bg.texture = load("res://assets/level_3_bg.png")
    bg.centered = false
    bg.position = Vector2.ZERO
    bg.z_index = -1
    add_child(bg)

    # Build walls: rects for collision and sprites for visuals
    walls = [
        Rect2(0, 0, 1024, 20), Rect2(0, 556, 1024, 20),
        Rect2(0, 0, 20, 576), Rect2(1004, 0, 20, 576),
        Rect2(130, 110, 120, 60), Rect2(350, 110, 120, 60), Rect2(560, 110, 120, 60), Rect2(780, 110, 120, 60),
        Rect2(130, 250, 120, 60), Rect2(350, 250, 120, 60), Rect2(560, 250, 120, 60), Rect2(780, 250, 120, 60),
        Rect2(130, 390, 120, 60), Rect2(350, 390, 120, 60), Rect2(560, 390, 120, 60), Rect2(780, 390, 120, 60),
        Rect2(880, 470, 120, 86)
    ]
    var wall_tex = load("res://assets/extra_garden_wall.png")
    for r in walls:
        var ws = Sprite2D.new()
        ws.texture = wall_tex
        ws.centered = false
        ws.position = r.position
        ws.scale = Vector2(r.size.x / 128.0, r.size.y / 128.0)
        add_child(ws)

    # Player
    player = Area2D.new()
    player.position = player_spawn
    player_sprite = Sprite2D.new()
    # Set up animation poses before using the sprite
    var rest_tex = load("res://assets/hero_sprite.png")
    var walk_tex = load("res://assets/hero_walk.png")
    Anim.set_poses(player_sprite, rest_tex, walk_tex)
    player_sprite.texture = rest_tex   # initial texture
    player.add_child(player_sprite)
    var player_shape = CollisionShape2D.new()
    var shape_circle = CircleShape2D.new()
    shape_circle.radius = player_half_size
    player_shape.shape = shape_circle
    player.add_child(player_shape)
    player.area_entered.connect(_on_player_touched)
    add_child(player)

    # Spawn dots (stars) using a dense grid, avoiding walls and power pellet spots
    var star_tex = load("res://assets/key_item.png")
    var grid_step = 45
    var wall_margin = 10.0
    for y0 in range(40, 520, grid_step):
        for x0 in range(40, 1000, grid_step):
            var pos = Vector2(x0, y0)
            if pos in pellet_positions:
                continue
            if _point_inside_walls(pos, wall_margin):
                continue
            _spawn_dot(pos, false, star_tex)
    # Power pellets (golden stars) at corners
    for pos in pellet_positions:
        _spawn_dot(pos, true, star_tex)
    # Final star in the dead-end corridor (hard-coded)
    var final_dot_pos = Vector2(840, 500)
    if not final_dot_pos in pellet_positions and not _point_inside_walls(final_dot_pos, wall_margin):
        _spawn_dot(final_dot_pos, false, star_tex)

    # Ghosts (moths)
    var moth_tex = load("res://assets/extra_patrol_moth.png")
    # Patrol ghost 1 (reddish tint, long route)
    _spawn_ghost(Vector2(75, 70), Color(0.9, 0.7, 0.7), moth_tex,
        [Vector2(75,70), Vector2(300,70), Vector2(300,210), Vector2(560,210), Vector2(560,350),
         Vector2(300,350), Vector2(300,490), Vector2(75,490), Vector2(75,70)])
    # Patrol ghost 2 (bluish tint, another loop)
    _spawn_ghost(Vector2(950, 70), Color(0.7, 0.7, 0.9), moth_tex,
        [Vector2(950,70), Vector2(730,70), Vector2(730,210), Vector2(560,210), Vector2(560,280),
         Vector2(730,280), Vector2(730,490), Vector2(950,490), Vector2(950,70)])
    # Hunter ghost (dark grey, no waypoints)
    _spawn_ghost(Vector2(512, 280), Color(0.5, 0.5, 0.5), moth_tex, [])

    # Status label
    var canvas = CanvasLayer.new()
    add_child(canvas)
    status_label = Label.new()
    status_label.position = Vector2(20, 20)
    status_label.add_theme_font_size_override("font_size", 24)
    canvas.add_child(status_label)

    # Skip title screen on non-first level or headless QA
    if DisplayServer.get_name() == "headless" or Game.level > 0:
        state = "playing"

func _spawn_dot(pos: Vector2, is_pellet: bool, tex: Texture2D) -> void:
    var dot = Area2D.new()
    dot.position = pos
    var sprite = Sprite2D.new()
    sprite.texture = tex
    if is_pellet:
        sprite.scale = Vector2(0.45, 0.45)
        sprite.modulate = Color(1.4, 1.2, 0.5)   # golden power star
    else:
        sprite.scale = Vector2(0.18, 0.18)
    dot.add_child(sprite)
    var shape = CollisionShape2D.new()
    var circle = CircleShape2D.new()
    circle.radius = 10.0
    shape.shape = circle
    dot.add_child(shape)
    dot.area_entered.connect(_on_dot_entered.bind(dot, is_pellet))
    add_child(dot)
    total_dots += 1

func _spawn_ghost(pos: Vector2, tint: Color, tex: Texture2D, route: Array) -> void:
    var ghost = Area2D.new()
    ghost.position = pos
    var sprite = Sprite2D.new()
    sprite.texture = tex
    sprite.modulate = tint
    sprite.scale = Vector2(0.65, 0.65)
    ghost.add_child(sprite)
    var shape = CollisionShape2D.new()
    var circle = CircleShape2D.new()
    circle.radius = 14.0
    shape.shape = circle
    ghost.add_child(shape)
    add_child(ghost)
    ghosts.append(ghost)
    ghost_sprites.append(sprite)
    ghost_tints.append(tint)
    ghost_home.append(pos)
    ghost_routes.append(route)
    ghost_route_index.append(0)
    ghost_frightened.append(false)

func _point_inside_walls(pt: Vector2, margin: float) -> bool:
    for r in walls:
        var expanded = Rect2(r.position - Vector2(margin, margin), r.size + Vector2(margin * 2, margin * 2))
        if expanded.has_point(pt):
            return true
    return false

func _on_dot_entered(area: Area2D, dot: Area2D, is_pellet: bool) -> void:
    if state != "playing" or area != player:
        return
    dot.queue_free()
    score += 1
    Sfx.play("pickup")
    if is_pellet:
        power_left = power_duration
        for i in ghosts.size():
            ghost_frightened[i] = true
    if score >= total_dots:
        state = "won"
        Sfx.play("win")
        status_label.text = "All stars restored! The night sky shines again!"
        Game.level_complete()

func _on_player_touched(area: Area2D) -> void:
    if state != "playing":
        return
    var idx = ghosts.find(area)
    if idx == -1:
        return
    # Moth touched
    if ghost_frightened[idx]:
        Sfx.play("pickup")
        ghosts[idx].position = ghost_home[idx]
        ghost_frightened[idx] = false
        return
    # Normal moth hit
    if hit_cooldown > 0.0:
        return
    lives -= 1
    hit_cooldown = hit_cooldown_time
    player.position = player_spawn
    player_sprite.modulate = Color(1.0, 0.45, 0.45)
    Sfx.play("hit")
    if lives <= 0:
        state = "over"
        Sfx.play("lose")
        status_label.text = "The light fades... Press Enter to restart"

func _hits_wall(pos: Vector2) -> bool:
    var half = Vector2(player_half_size, player_half_size)
    var player_rect = Rect2(pos - half, half * 2.0)
    for w in walls:
        if player_rect.intersects(w):
            return true
    return false

func _process(delta: float) -> void:
    # Title screen
    if state == "title":
        status_label.text = "GLUTTON GROVE - Press Enter to start"
        if Input.is_action_just_pressed("ui_accept"):
            state = "playing"
        return
    if state == "won":
        return
    if state == "over":
        if Input.is_action_just_pressed("ui_accept"):
            get_tree().reload_current_scene()
        return

    # Hit cooldown timer
    if hit_cooldown > 0.0:
        hit_cooldown -= delta
        if hit_cooldown <= 0.0:
            player_sprite.modulate = Color(1, 1, 1)

    # Power timer countdown
    if power_left > 0.0:
        power_left -= delta
        if power_left <= 0.0:
            for i in ghosts.size():
                ghost_frightened[i] = false

    # Move ghosts
    for i in ghosts.size():
        var ghost = ghosts[i]
        var sprite = ghost_sprites[i]
        if ghost_frightened[i]:
            sprite.modulate = Color(0.5, 0.6, 1.4)
            var away = (ghost.position - player.position).normalized()
            ghost.position += away * frightened_speed * delta
            ghost.position = ghost.position.clamp(Vector2(40, 40), Vector2(984, 536))
        else:
            sprite.modulate = ghost_tints[i]
            if ghost_routes[i].size() > 0:
                # Patrol moth
                var target = ghost_routes[i][ghost_route_index[i]]
                ghost.position = ghost.position.move_toward(target, patrol_speed * delta)
                if ghost.position.distance_to(target) < 2.0:
                    ghost_route_index[i] = (ghost_route_index[i] + 1) % ghost_routes[i].size()
            else:
                # Hunter moth – moves directly toward player
                var toward = (player.position - ghost.position).normalized()
                ghost.position += toward * hunter_speed * delta

    # Player input
    var velocity = Vector2.ZERO
    if Input.is_action_pressed("ui_right"):
        velocity.x += 1.0
    if Input.is_action_pressed("ui_left"):
        velocity.x -= 1.0
    if Input.is_action_pressed("ui_down"):
        velocity.y += 1.0
    if Input.is_action_pressed("ui_up"):
        velocity.y -= 1.0

    var motion = velocity.normalized() * player_speed * delta
    var is_moving = velocity.length() > 0.01

    # Axis‑separated collision
    var new_x = player.position + Vector2(motion.x, 0)
    if not _hits_wall(new_x):
        player.position = new_x
    var new_y = player.position + Vector2(0, motion.y)
    if not _hits_wall(new_y):
        player.position = new_y

    # Player animation: walk when moving, stand still otherwise
    if is_moving:
        var dir_x = sign(velocity.x) if abs(velocity.x) > 0.01 else 0.0
        Anim.walk(player_sprite, true, dir_x)
    else:
        Anim.walk(player_sprite, false, 0.0)

    # Ghosts are floating moths – use hover animation
    for i in ghosts.size():
        Anim.hover(ghost_sprites[i])

    # Update status label
    var power_text = ""
    if power_left > 0.0:
        power_text = "   POWER %ds!" % int(ceil(power_left))
    status_label.text = "Stars: %d / %d   Lives: %d%s" % [score, total_dots, lives, power_text]

